body.query:
query Participant($countryCode: String!) {
  nodeCountry(countryCode: $countryCode) {
    title
    address
    gbifRegion
    participationStatus
    participant {
      membershipStart
      nodeEstablishmentDate
    }
    ...ParticipantSummary
    ...CountryKeyParticipation
  }
}

fragment ParticipantSummary on Node {
  title
  gbifRegion
  participationStatus
  participant {
    membershipStart
    nodeEstablishmentDate
    participantUrl
    rssFeeds {
      label
      url
    }
    newsletters {
      label
      url
    }
    linksToSocialMedia {
      label
      url
    }
  }
  headOfDelegation: contacts(type: "HEAD_OF_DELEGATION") {
    key
    firstName
    lastName
  }
  participantNodeManager: contacts(type: "NODE_MANAGER") {
    key
    firstName
    lastName
  }
  directoryNodes {
    nodeUrl
  }
}

fragment CountryKeyParticipation on Node {
  participant {
    progressAndPlans
    nodeMission
    nodeFunding
    nodeHistory
    nodeStructure
    participationStatus
  }
  ...NodeContacts
}

fragment NodeContacts on Node {
  contacts {
    key
    firstName
    surname
    lastName
    institutionName

    organization
    position
    roles
    type

    address
    city
    postalCode
    province
    country

    homepage
    email
    phone
    userId
  }
}
